def solve(xs):
    if not xs:
        return ""

    common_prefix = xs[0]
    for i in range(1, len(xs)):
        while xs[i].startswith(common_prefix) and i < len(xs):
            common_prefix = xs[i][:len(common_prefix)]
        else:
            break

    return common_prefix
